CREATE TEMPORARY VIEW cheapest_list_${grass_region_without_quote} AS
select
     cspu_id
    ,item_id
    ,exp_tag
from(
    SELECT
         cspu_id
        ,item_id
    FROM srdi_mart.dwd_sr_data_warehouse_pb_one_variation_model_minf
    where grass_region in (${grass_region}) and regional_date=${regional_date} and regional_hour=${regional_hour}
    group by 1,2
) a
lateral view explode(array('T1','T2')) b as exp_tag -- 按照实验策略数量，进行维表复制拷贝，v3的第一次发版只有一个实验策略
;
--sql_divide_splitter--
-- 获取最近7天，最大可用且<当前小时的分区，以此获取上一个可用的历史分区，还会外加质量检测：>5%的版本日期=（当日+昨日）就报错
-- 所以这个表也得设置成单并发度任务。
set last_partition_${grass_region_without_quote} = (
select
    max(time_str)
from(
    SELECT
        concat(regional_date,'_',if(regional_hour<10,concat('0',regional_hour),regional_hour)) as  time_str
    FROM srdi_mart.dwd_sr_data_warehouse_pb_rcmd_replace_pruning_v3_hf
    where grass_region in (${grass_region}) and regional_date between date_sub(${regional_date}, 6) and ${regional_date}
    group by regional_date,regional_hour
) a
where time_str<concat(${regional_date},'_',if(${regional_hour}<10,concat('0',${regional_hour}),${regional_hour}))
);
--sql_divide_splitter--

CREATE TEMPORARY VIEW last_pruning_${grass_region_without_quote} AS
SELECT
     exp_tag
    ,cspu_id
    ,item_id
    ,version_date
    ,pruning_tag
FROM srdi_mart.dwd_sr_data_warehouse_pb_rcmd_replace_pruning_v3_hf
where grass_region in (${grass_region}) and regional_date = split(${last_partition_${grass_region_without_quote}},'_')[0]
and regional_hour = cast(split(${last_partition_${grass_region_without_quote}},'_')[1] as int)
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW accumulated_pruning_list_${grass_region_without_quote} AS
SELECT
     if(a.exp_tag is not null ,a.exp_tag,b.exp_tag) as exp_tag
    ,if(a.cspu_id is not null ,a.cspu_id,b.cspu_id) as cspu_id
    ,if(a.item_id is not null ,a.item_id,b.item_id) as item_id
    ,a.version_date
    ,a.pruning_tag
FROM last_pruning_${grass_region_without_quote} a
full outer join cheapest_list_${grass_region_without_quote} b on a.item_id=b.item_id and a.cspu_id=b.cspu_id and a.exp_tag=b.exp_tag
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW pruning_exp_${grass_region_without_quote} AS
SELECT
     exp_tag
    ,item_id
    ,pruning_tag
FROM srdi_mart.dim_sr_data_warehouse_pb_rcmd_replace_pruning_tag_df
where grass_region in (${grass_region})
and local_date = data_infra.max_pt('srdi_mart.dim_sr_data_warehouse_pb_rcmd_replace_pruning_tag_df', 'local_date', "grass_region=${grass_region} and local_date<${regional_date}")
and exp_tag = 'T1'
;
--sql_divide_splitter--

INSERT OVERWRITE TABLE ${schema}.dwd_sr_data_warehouse_pb_rcmd_replace_pruning_v3_hf
PARTITION (grass_region = ${grass_region}, regional_date = ${regional_date}, regional_hour = ${regional_hour})
SELECT
     d.exp_tag
    ,d.cspu_id
    ,d.item_id
    ,if(update_flag
        ,new_pruning_tag
        ,current_pruning_tag
      ) as pruning_tag
    ,if(update_flag
       ,if(new_pruning_tag is not null
          ,cast(replace(${regional_date}, '-', '') as int) -- 纯新的或者要求升级的，给定一个版本值
          ,null --没有的等待质检信息
          )
       ,current_version_date
     ) as version_date --版本信息是线上流转的关键信息之一。
from (
    select
         a.exp_tag
        ,a.cspu_id
        ,a.item_id
        ,if(a.version_date is null --这里其实包含两种：1）本次运行新补充的；2）上次运行没有质检信息的
           ,true
           ,false
         ) as update_flag
        ,a.pruning_tag  as current_pruning_tag
        ,a.version_date as current_version_date
        ,if(a.exp_tag = 'T1', c.pruning_tag, 'obvious_good') as new_pruning_tag
    from accumulated_pruning_list_${grass_region_without_quote} a
    left join pruning_exp_${grass_region_without_quote} c on a.item_id=c.item_id and a.exp_tag=c.exp_tag
) d
;
